package game;
import com.badlogic.gdx.math.*;
import java.util.*;
/** Behavioral controller checks without a graphics context. */
public final class FeelChecks {
 static int checks;static void test(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public static void run(){PlayerMotor motor=new PlayerMotor();Vector3 displacement=motor.step(new Vector3(1,0,0),.016f,false);test(motor.velocity.x>0&&motor.velocity.x<1,"Immediate response without teleporting to full speed");for(int i=0;i<30;i++)motor.step(new Vector3(1,0,0),.016f,false);test(Math.abs(motor.velocity.x-4.6f)<.01f,"Reach run speed");float previous=motor.velocity.x;motor.step(new Vector3(),.016f,false);test(motor.velocity.x<previous&&motor.velocity.x>0,"Smooth deceleration");for(int i=0;i<20;i++)motor.step(new Vector3(),.016f,false);test(motor.velocity.len()<.01f,"Stop without sliding");motor.heading=350;motor.turn(new Vector3(-.17f,0,-.98f),.016f,17);test(motor.heading>350||motor.heading<10,"Turn across shortest arc");motor.dodge(new Vector3(0,0,-1));float total=0;for(int i=0;i<34;i++)total+=motor.step(new Vector3(),.01f,false).len();test(Math.abs(total-PlayerMotor.DODGE_DISTANCE)<.015f&&!motor.dodging(),"Eased dodge preserves intended distance");
 CombatController attack=new CombatController();test(attack.start(new Vector3(0,0,-1)),"Begin attack");test(!attack.start(Vector3.X),"Cannot restart during anticipation");test(!attack.advance(.10f),"Anticipation has no damage");test(attack.advance(.05f),"Strike occurs at contact");attack.struck=true;test(!attack.advance(.10f),"Strike once");attack.impact(false);test(attack.tickReal(.016f)==0,"Impact freezes simulation briefly");for(int i=0;i<8;i++)attack.tickReal(.016f);test(attack.tickReal(.016f)>0,"Hit-stop releases");
 ArrayList<Rectangle> labels=new ArrayList<>();for(int i=0;i<18;i++){Rectangle r=LootLayout.place(720,430,160,labels);test(r!=null,"Place stacked loot "+i);}for(int i=0;i<labels.size();i++)for(int j=i+1;j<labels.size();j++)test(!labels.get(i).overlaps(labels.get(j)),"Loot labels do not overlap");test(TestArea.height(0,-4.5f)==.6f,"Ramp has traversable elevation");test(TestArea.height(4,-4.5f)==1.2f,"Cliff stays raised beside ramp");System.out.println("PASS: "+checks+" movement, attack timing, hit-stop, elevation, and loot layout checks.");}
}
